use std::fs

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut cap = 1
    let mut first = true
    // least recent first
    let mut ks: Vec<int> = []
    let mut vs: Vec<int> = []
    for line in text.lines() {
        let parts = line.split_whitespace().map(|s| s.to_string()).collect::<Vec<string>>()
        if parts.len() == 0 { continue }
        if first {
            cap = parts[0].parse::<int>().unwrap_or(1)
            first = false
            continue
        }
        let cmd = parts[0]
        if cmd == "put" {
            let k = parts[1].parse::<int>().unwrap_or(0)
            let v = parts[2].parse::<int>().unwrap_or(0)
            let mut nk: Vec<int> = []
            let mut nv: Vec<int> = []
            let mut i = 0
            while i < ks.len() {
                if ks[i] != k {
                    nk.push(ks[i])
                    nv.push(vs[i])
                }
                i += 1
            }
            nk.push(k)
            nv.push(v)
            if (nk.len() as int) > cap {
                println("evict ${nk[0]}")
                let mut ek: Vec<int> = []
                let mut ev: Vec<int> = []
                let mut j = 1
                while j < nk.len() {
                    ek.push(nk[j])
                    ev.push(nv[j])
                    j += 1
                }
                nk = ek
                nv = ev
            }
            ks = nk
            vs = nv
        } else if cmd == "get" {
            let k = parts[1].parse::<int>().unwrap_or(0)
            let mut found = -1
            let mut nk: Vec<int> = []
            let mut nv: Vec<int> = []
            let mut i = 0
            while i < ks.len() {
                if ks[i] != k {
                    nk.push(ks[i])
                    nv.push(vs[i])
                } else {
                    found = vs[i]
                }
                i += 1
            }
            if found != -1 || ks.len() != nk.len() {
                nk.push(k)
                nv.push(found)
                ks = nk
                vs = nv
            }
            println("${found}")
        } else if cmd == "keys" {
            if ks.len() == 0 {
                println("<empty>")
            } else {
                let mut out = ""
                let mut i = ks.len()
                while i > 0 {
                    i -= 1
                    if out != "" { out = out + " " }
                    out = out + "${ks[i]}"
                }
                println("${out}")
            }
        }
    }
}

